    stylesCss:
      '@keyframes tlHeaderIn {\n  0% {\n    opacity: 0;\n    transform: translateY(-14px);\n  }\n  100% {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n@keyframes tlRailGrow {\n  0% {\n    transform: scaleY(0);\n  }\n  100% {\n    transform: scaleY(1);\n  }\n}\n\n@keyframes tlItemIn {\n  0% {\n    opacity: 0;\n    transform: translateX(24px);\n  }\n  100% {\n    opacity: 1;\n    transform: translateX(0);\n  }\n}\n\n.tl-card {\n  width: 100%;\n  height: 100%;\n  padding: 52px;\n  background: var(--tt-bg);\n  display: flex;\n}\n\n.tl-frame {\n  width: 100%;\n  height: 100%;\n  border-radius: 32px;\n  border: 2px solid var(--tt-border);\n  background: var(--tt-surface);\n  padding: 48px 54px;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  gap: 20px;\n}\n\n.tl-header {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  animation: tlHeaderIn 480ms cubic-bezier(0.22, 1, 0.36, 1) 40ms both;\n}\n\n.tl-badge {\n  align-self: flex-start;\n  padding: 8px 16px;\n  border-radius: 9999px;\n  background: var(--tt-badge-bg);\n  color: var(--tt-badge-text);\n  font-family: var(--tt-font-mono);\n  font-size: 15px;\n  font-weight: 600;\n  letter-spacing: 0.08em;\n}\n\n.tl-title {\n  font-family: var(--tt-font-sans);\n  font-size: 38px;\n  font-weight: 700;\n  line-height: 1.22;\n  letter-spacing: -0.02em;\n  color: var(--tt-text-primary);\n}\n\n.tl-body {\n  position: relative;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  padding-left: 32px;\n}\n\n.tl-rail {\n  position: absolute;\n  left: 9px;\n  top: 24px;\n  bottom: 24px;\n  width: 4px;\n  border-radius: 9999px;\n  background: linear-gradient(180deg, var(--tt-accent), var(--tt-accent-secondary));\n  transform-origin: top center;\n  animation: tlRailGrow 2600ms cubic-bezier(0.22, 1, 0.36, 1) 250ms both;\n}\n\n.tl-list {\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.tl-item {\n  position: relative;\n  display: flex;\n  align-items: center;\n  animation: tlItemIn 520ms cubic-bezier(0.22, 1, 0.36, 1) both;\n}\n\n.tl-dot {\n  position: absolute;\n  left: -30px;\n  width: 18px;\n  height: 18px;\n  border-radius: 9999px;\n  background: var(--tt-accent);\n  border: 4px solid var(--tt-surface);\n}\n\n.tl-content {\n  width: 100%;\n  padding: 18px 22px;\n  border-radius: 18px;\n  background: var(--tt-surface-elevated);\n  border: 1px solid var(--tt-border);\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.tl-row-top {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.tl-step {\n  padding: 4px 10px;\n  border-radius: 6px;\n  background: var(--tt-badge-bg);\n  color: var(--tt-badge-text);\n  font-family: var(--tt-font-mono);\n  font-size: 14px;\n  font-weight: 700;\n}\n\n.tl-headline {\n  font-family: var(--tt-font-sans);\n  font-size: 21px;\n  font-weight: 700;\n  color: var(--tt-text-primary);\n}\n\n.tl-detail {\n  font-family: var(--tt-font-sans);\n  font-size: 18px;\n  line-height: 1.35;\n  color: var(--tt-text-secondary);\n}\n\n.tl-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding-top: 18px;\n  border-top: 1px solid var(--tt-border);\n  font-family: var(--tt-font-mono);\n  font-size: 16px;\n  color: var(--tt-text-muted);\n  animation: tlHeaderIn 500ms cubic-bezier(0.22, 1, 0.36, 1) 2800ms both;\n}\n\n.tl-brand {\n  color: var(--tt-accent);\n  font-weight: 700;\n}\n\nbody[data-tt-orientation="landscape"] .tl-card {\n  padding: 28px 40px;\n}\n\nbody[data-tt-orientation="landscape"] .tl-frame {\n  padding: 28px 38px;\n  gap: 12px;\n}\n\nbody[data-tt-orientation="landscape"] .tl-content {\n  padding: 10px 16px;\n}\n',
