      '.thread-card {\n  width: 100%;\n  height: 100%;\n  padding: 56px;\n  background: var(--tt-bg);\n  display: flex;\n}\n\n.thread-frame {\n  width: 100%;\n  height: 100%;\n  border-radius: 32px;\n  border: 2px solid var(--tt-border);\n  background: var(--tt-surface);\n  padding: 52px 58px;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  gap: 22px;\n}\n\n.thread-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n}\n\n.author-row {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n.monogram {\n  width: 58px;\n  height: 58px;\n  border-radius: 9999px;\n  background: var(--tt-badge-bg);\n  border: 2px solid var(--tt-accent);\n  color: var(--tt-badge-text);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-family: var(--tt-font-metric);\n  font-size: 21px;\n  font-weight: 700;\n}\n\n.author-name {\n  font-family: var(--tt-font-sans);\n  font-size: 23px;\n  font-weight: 700;\n  color: var(--tt-text-primary);\n}\n\n.author-handle {\n  font-family: var(--tt-font-mono);\n  font-size: 17px;\n  color: var(--tt-text-muted);\n}\n\n.thread-badge {\n  padding: 9px 18px;\n  border-radius: 9999px;\n  background: var(--tt-badge-bg);\n  color: var(--tt-badge-text);\n  font-family: var(--tt-font-mono);\n  font-size: 16px;\n  font-weight: 600;\n  letter-spacing: 0.08em;\n}\n\n.thread-headline {\n  font-family: var(--tt-font-sans);\n  font-size: 36px;\n  font-weight: 700;\n  line-height: 1.24;\n  letter-spacing: -0.02em;\n  color: var(--tt-text-primary);\n  overflow: hidden;\n}\n\n.points-list {\n  list-style: none;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  gap: 16px;\n}\n\n.point-row {\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  padding: 20px 24px;\n  border-radius: 18px;\n  background: var(--tt-surface-elevated);\n  border: 1px solid var(--tt-border);\n}\n\n.point-index {\n  font-family: var(--tt-font-mono);\n  font-size: 20px;\n  font-weight: 600;\n  color: var(--tt-accent);\n  flex-shrink: 0;\n}\n\n.point-text {\n  font-family: var(--tt-font-sans);\n  font-size: 21px;\n  line-height: 1.35;\n  color: var(--tt-text-secondary);\n}\n\n.thread-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding-top: 20px;\n  border-top: 1px solid var(--tt-border);\n  font-family: var(--tt-font-mono);\n  font-size: 17px;\n  color: var(--tt-text-muted);\n}\n\n.brand {\n  color: var(--tt-accent);\n  font-weight: 600;\n}\n\nbody[data-tt-orientation="landscape"] .thread-card {\n  padding: 32px 44px;\n}\n\nbody[data-tt-orientation="landscape"] .thread-frame {\n  padding: 32px 42px;\n  gap: 14px;\n}\n\nbody[data-tt-orientation="landscape"] .point-row {\n  padding: 12px 18px;\n}\n',
